"""Exclude generated bytecode only after proving all scientific source matches."""
import hashlib
from pathlib import Path

c=Path('/home/aryan.jha/kamiak_jobs/tadmm_review_nov09_persistent_caps')
p=c/'execution-source.sha256';text=p.read_text();kept=[];mismatch=[]
for line in text.splitlines():
    digest,rel=line.split('  ',1)
    actual=hashlib.sha256((c/'source'/rel).read_bytes()).hexdigest()
    if digest!=actual:
        assert '/__pycache__/' in rel and rel.endswith('.pyc'),rel
        mismatch.append(rel)
    if '/__pycache__/' not in rel:kept.append(line+'\n')
assert len(mismatch)==1,mismatch
backup=c/'campaign/initial-execution-source-with-cache.sha256'
assert not backup.exists()
backup.write_text(text)
p.write_text(''.join(kept))
(c/'campaign/cache-manifest-repair.txt').write_text('All non-bytecode source hashes verified unchanged. Only generated cache mismatch:\n'+'\n'.join(mismatch)+'\nOriginal pre-solve failed jobs31665845/31665847 retained. Generated caches excluded from execution-source manifest; no numerical/input file changed.\n')
print((c/'campaign/cache-manifest-repair.txt').read_text())
